def symbol_id(label):
 label=str(label)
 if len(label)==1 and label in SUPPORTED:return SUPPORTED.index(label)
 return 1000+int.from_bytes(hashlib.sha256(label.encode()).digest()[:4],"big")
def stimulus(label,input_neuron=None):
 sid=symbol_id(label)
 e=_ENTRIES[sid%len(_ENTRIES)]
 inp=e["input_neuron"] if input_neuron is None else int(input_neuron)
 t=0;times=[0]
 for d in e["intervals"]:t+=d;times.append(t)
 return {"format":FORMAT,"label":str(label),"stimulus_id":sid,"calibrated_entry":sid%len(_ENTRIES),
 "input_neuron":inp,"intervals":list(e["intervals"]),"pulse_count":6,"total_duration_ms":20,
 "total_input":AMPLITUDE*6,"pulses":[{"dt":dt,"amp":AMPLITUDE,"input_neuron":inp} for dt in times]}
def inject_stimulus(brain,label,input_neuron=None,start=1):
 spec=stimulus(label,input_neuron)
 for p in spec["pulses"]:brain.inject(p["input_neuron"],p["amp"],start+p["dt"],origin=p["input_neuron"])
 return spec
